    @property
    def packs(self):
        if self._packs is None:
            try:
                from pygit import pack
            except ImportError:
                self._packs = []
            else:
                self._packs = pack.load_packs(self.dir / "pack")
        return self._packs

    def refresh_packs(self) -> None:
