    target = Path(a.directory)
    target.mkdir(parents=True, exist_ok=True)
    init(target, bare=a.bare, initial_branch=a.initial_branch, quiet=a.quiet)
    return 0


@command("hash-object")
def cmd_hash_object(args):
    p = parser("hash-object")
