    target = refs.symbolic_target(a.name)
    if target is None:
        if a.quiet:
            return 1
        raise GitError(f"ref {a.name} is not a symbolic ref")
    if a.short:
        for pre in ("refs/heads/", "refs/tags/", "refs/remotes/"):
            if target.startswith(pre):
                target = target[len(pre):]
                break
    out(target.encode() + b"\n")
    return 0


