        meta, _, name = line.partition(b"\t")
        mode, _, rest = meta.partition(b" ")
        _, _, oid = rest.partition(b" ")
        if not a.z and name.startswith(b'"'):
            from pygit.quote import unquote_path
            name = unquote_path(name)
