"""`.gitignore` rules and git's wildmatch.

Sources, highest priority first (the last matching pattern within the
highest-priority source that matches decides):
  1. `.gitignore` files, the deepest directory first;
  2. `$GIT_DIR/info/exclude`;
  3. the file named by `core.excludesFile` (default
     `$XDG_CONFIG_HOME/git/ignore`).
A path inside an excluded directory is excluded, whatever the patterns say
about the path itself: git does not descend into ignored directories.
"""

from __future__ import annotations

import os
from dataclasses import dataclass
from pathlib import Path


# -- wildmatch (a port of git's wildmatch.c) -----------------------------------------

_MATCH, _NOMATCH, _ABORT_ALL, _ABORT_TO_STARSTAR = 1, 0, -1, -2

_CLASSES = {
    b"alnum": lambda c: chr(c).isalnum() and c < 128,
    b"alpha": lambda c: chr(c).isalpha() and c < 128,
    b"blank": lambda c: c in (0x20, 0x09),
    b"cntrl": lambda c: c < 0x20 or c == 0x7F,
    b"digit": lambda c: 0x30 <= c <= 0x39,
    b"graph": lambda c: 0x21 <= c <= 0x7E,
    b"lower": lambda c: 0x61 <= c <= 0x7A,
    b"print": lambda c: 0x20 <= c <= 0x7E,
    b"punct": lambda c: 0x21 <= c <= 0x7E and not chr(c).isalnum(),
    b"space": lambda c: c in b" \t\n\r\f\v",
    b"upper": lambda c: 0x41 <= c <= 0x5A,
    b"xdigit": lambda c: chr(c) in "0123456789abcdefABCDEF",
}


def _lower(c: int) -> int:
    return c + 32 if 0x41 <= c <= 0x5A else c


def _dowild(p: bytes, pi: int, t: bytes, ti: int, icase: bool, pathname: bool) -> int:
    plen, tlen = len(p), len(t)
    while pi < plen:
        pc = p[pi]
        if ti >= tlen and pc != 0x2A:  # '*'
            return _ABORT_ALL
        tc = t[ti] if ti < tlen else 0
        if icase:
            tc = _lower(tc)
            pc = _lower(pc)
        if pc == 0x5C:  # '\\' escapes the next pattern char
            pi += 1
            if pi >= plen:
                return _NOMATCH
            pc2 = _lower(p[pi]) if icase else p[pi]
            if tc != pc2:
                return _NOMATCH
        elif pc == 0x3F:  # '?'
            if pathname and tc == 0x2F:
                return _NOMATCH
        elif pc == 0x2A:  # '*'
            pi += 1
            match_slash = False
            if pi < plen and p[pi] == 0x2A:
                prev_pi = pi - 1
                while pi < plen and p[pi] == 0x2A:
                    pi += 1
                if not pathname:
                    match_slash = True
                elif (prev_pi == 0 or p[prev_pi - 1] == 0x2F) and (pi >= plen or p[pi] == 0x2F or
                                                                    (p[pi] == 0x5C and pi + 1 < plen and p[pi + 1] == 0x2F)):
                    # "**/" at a component boundary: matches zero or more dirs.
                    if pi < plen and p[pi] == 0x2F and _dowild(p, pi + 1, t, ti, icase, pathname) == _MATCH:
                        return _MATCH
                    match_slash = True
                else:
                    match_slash = False
            else:
                match_slash = not pathname
            if pi >= plen:
                # Trailing '*' or '**'.
                if not match_slash and t.find(b"/", ti) >= 0:
                    return _ABORT_TO_STARSTAR
                return _MATCH
            if not match_slash and p[pi] == 0x2F:
                slash = t.find(b"/", ti)
                if slash < 0:
                    return _ABORT_ALL
                ti = slash
                pi_next = pi
                # Continue matching the '/' normally.
                tc = t[ti]
                pi = pi_next
                continue
            while True:
                if ti >= tlen:
                    break
                tc = t[ti]
                # Quick skip: next literal pattern char must match.
                r = _dowild(p, pi, t, ti, icase, pathname)
                if r != _NOMATCH:
                    if not match_slash or r != _ABORT_TO_STARSTAR:
                        return r
                elif not match_slash and tc == 0x2F:
                    return _ABORT_TO_STARSTAR
                ti += 1
            return _ABORT_ALL
        elif pc == 0x5B:  # '['
            pi += 1
            if pi >= plen:
                return _ABORT_ALL
            negated = p[pi] in (0x21, 0x5E)  # '!' or '^'
            if negated:
                pi += 1
            prev = -1
            matched = False
            first = True
            while True:
                if pi >= plen:
                    return _ABORT_ALL
                c = p[pi]
                if c == 0x5D and not first:  # ']'
                    break
                first = False
                if c == 0x5C:
                    pi += 1
                    if pi >= plen:
                        return _ABORT_ALL
                    c = p[pi]
                    if tc == (_lower(c) if icase else c):
                        matched = True
                    prev = c
                elif c == 0x2D and prev >= 0 and pi + 1 < plen and p[pi + 1] != 0x5D:  # range
                    pi += 1
                    hi = p[pi]
                    if hi == 0x5C:
                        pi += 1
                        if pi >= plen:
                            return _ABORT_ALL
                        hi = p[pi]
                    if prev <= t[ti] <= hi:
                        matched = True
                    if icase and 0x61 <= tc <= 0x7A:
                        up = tc - 32
                        if prev <= up <= hi:
                            matched = True
                    prev = -1
                elif c == 0x5B and pi + 1 < plen and p[pi + 1] == 0x3A:  # [:class:]
                    end = p.find(b":]", pi + 2)
                    if end < 0:
                        # Not a class: treat '[' literally.
                        if tc == c:
                            matched = True
                        prev = c
                    else:
                        cls = p[pi + 2:end]
                        fn = _CLASSES.get(cls)
                        if fn is None:
                            return _ABORT_ALL
                        ch = t[ti]
                        if fn(ch) or (icase and cls == b"upper" and _CLASSES[b"lower"](ch)):
                            matched = True
                        pi = end + 1
                        prev = -1
                else:
                    if tc == (_lower(c) if icase else c):
                        matched = True
                    prev = c
                pi += 1
            if matched == negated or (pathname and tc == 0x2F):
                return _NOMATCH
        else:
            if tc != pc:
                return _NOMATCH
        pi += 1
        ti += 1
    return _MATCH if ti >= tlen else _NOMATCH


def wildmatch(pattern: bytes, text: bytes, icase: bool = False, pathname: bool = True) -> bool:
    return _dowild(pattern, 0, text, 0, icase, pathname) == _MATCH


# -- patterns ----------------------------------------------------------------------

@dataclass
class Pattern:
    pattern: bytes      # as matched (leading '/' and trailing '/' removed)
    raw: bytes          # the line as written (for check-ignore -v)
    base: bytes         # directory of the .gitignore, "" or "dir/"
