    for c in st.unstaged:
        entries.setdefault(c.path, [" ", " ", None])
        entries[c.path][1] = c.status
    for path, code in st.unmerged:
        entries[path] = [code[0], code[1], None]
    for path in sorted(entries):
        x, y, orig = entries[path]
