    mode = "mixed"
    quiet = False
    revs, paths = [], []
    dashdash = False
    for arg in args:
        if dashdash:
            paths.append(arg)
        elif arg == "--":
            dashdash = True
        elif arg in ("--soft", "--mixed", "--hard", "--merge", "--keep"):
            mode = arg[2:]
        elif arg in ("-q", "--quiet"):
            quiet = True
        elif arg.startswith("-"):
            raise GitError(f"unknown option '{arg}'")
        else:
            revs.append(arg)
