            res.say(path, f"CONFLICT (add/add): Merge conflict in {_name(path)}")
        elif oid == o[1] and o[1] != t[1] and xdiff.is_binary(self.odb.read(o[1])[1] + self.odb.read(t[1])[1]):
            res.say(path, f"CONFLICT (content): Merge conflict in {_name(path)}")
        elif o[1] == t[1] or (b is not None and (b[1] == o[1] or b[1] == t[1])):
            res.say(path, f"CONFLICT (modify/modify): mode conflict in {_name(path)}")
        else:
