@command("merge-base")
def cmd_merge_base(args):
    repo = find_repo()
    all_ = is_anc = False
    revs = []
    for arg in args:
        if arg in ("-a", "--all"):
            all_ = True
        elif arg == "--is-ancestor":
            is_anc = True
        elif arg.startswith("-"):
            raise GitError(f"unknown option '{arg}'")
