    v = (cfg.get("merge.conflictStyle") or "merge").lower()
    return {"diff3": xmerge.STYLE_DIFF3, "zdiff3": xmerge.STYLE_ZEALOUS_DIFF3}.get(v, xmerge.STYLE_MERGE)

