"""Fuzz pygit.diffcore.detect_renames against `git diff --no-index -M`."""
import hashlib
import os
import random
import shutil
import subprocess
import sys
import tempfile

sys.path.insert(0, os.path.join(os.path.dirname(__file__), ".."))
from pygit import diffcore  # noqa: E402


class FakeOdb:
    def __init__(self):
        self.blobs = {}

    def add(self, data):
        oid = hashlib.sha1(b"blob %d\0" % len(data) + data).hexdigest()
        self.blobs[oid] = data
        return oid

    def read(self, oid):
        return b"blob", self.blobs[oid]


def text(rng, n):
    words = ["alpha", "beta", "gamma", "delta", "x = 1;", "return y;", "{", "}", "", "# note"]
    return "".join(rng.choice(words) + (" %d" % rng.randint(0, 9) if rng.random() < 0.5 else "") + "\n"
                   for _ in range(n)).encode()


def edit(rng, data, frac):
    lines = data.split(b"\n")
    for _ in range(int(len(lines) * frac)):
        i = rng.randrange(len(lines))
        lines[i] = b"changed %d" % rng.randint(0, 999)
    if rng.random() < 0.3:
        lines.insert(rng.randrange(len(lines) + 1), b"inserted line")
    return b"\n".join(lines)


def main(n, seed):
    rng = random.Random(seed)
    bad = 0
    for it in range(n):
        tmp = tempfile.mkdtemp()
        A, B = os.path.join(tmp, "A"), os.path.join(tmp, "B")
        os.makedirs(A)
        os.makedirs(B)
        odb = FakeOdb()
        old, new = {}, {}
        names = ["a.txt", "b.txt", "c.c", "d/e.txt", "f/a.txt", "g.md"]
        for k in range(rng.randint(1, 5)):
            name = rng.choice(names) if rng.random() < 0.5 else f"src{k}.txt"
            if name in old:
                continue
            data = text(rng, rng.randint(1, 40))
            old[name.encode()] = data
            frac = rng.choice([0.0, 0.1, 0.3, 0.45, 0.5, 0.55, 0.7, 1.0])
            dname = rng.choice(names + [f"dst{k}.txt", f"sub/dst{k}.txt"])
            if dname in [n.decode() for n in new] or dname == name:
                dname = f"other{k}/{os.path.basename(name)}"
            new[dname.encode()] = edit(rng, data, frac) if frac else data
        for root, files in ((A, old), (B, new)):
            for p, d in files.items():
                fp = os.path.join(root, p.decode())
                os.makedirs(os.path.dirname(fp), exist_ok=True)
                open(fp, "wb").write(d)
        g = subprocess.run(["git", "diff", "--no-index", "-M", "--name-status", "A", "B"],
                           cwd=tmp, stdout=subprocess.PIPE).stdout.decode()
        git_r = sorted(l.split("\t")[0][1:] + " " + l.split("\t")[1][2:] + " " + l.split("\t")[2][2:]
                       for l in g.splitlines() if l.startswith("R"))
        om = {p: (0o100644, odb.add(d)) for p, d in old.items()}
        nm = {p: (0o100644, odb.add(d)) for p, d in new.items()}
        mine = sorted("%03d %s %s" % (s, a.decode(), b.decode()) for a, b, s in diffcore.detect_renames(odb, om, nm))
        if mine != git_r:
            bad += 1
            if bad <= 3:
                print(f"--- {it}\ngit:  {git_r}\nmine: {mine}")
        shutil.rmtree(tmp)
    print(f"{n - bad}/{n} identical")


if __name__ == "__main__":
    main(int(sys.argv[1]), int(sys.argv[2]))

