    if "name-only" in formats:
        parts.append(diffout.name_only(pairs))
    if "name-status" in formats:
        parts.append(diffout.name_status(pairs))
    text = b"".join(parts)
    if "patch" in formats:
        patch = diffout.patch(repo, pairs, contents)
        text = text + (b"\n" if text else b"") + patch
    return text

